import { isCommitEnter } from './keyboard'

export type RulesKeyAction = 'next' | 'prev' | 'accept' | 'close' | 'open' | 'showAll'

export interface RulesKey {
  key: string
  shiftKey: boolean
  ctrlKey: boolean
  altKey: boolean
  metaKey: boolean
  isComposing?: boolean
  keyCode?: number
}

export interface RulesKeyContext {
  /** The completion list is shown and has at least one item. */
  popupOpen: boolean
  /** Text of the current line before the caret. */
  beforeCaret: string
  hasSelection: boolean
  /** The list was closed with Esc at this caret position – Tab moves focus instead of reopening it. */
  dismissed: boolean
}

/** What the editor does with a keydown; null = leave the key to the browser (typing, caret, focus moves). */
export function rulesEditorKey(e: RulesKey, ctx: RulesKeyContext): RulesKeyAction | null {
  // Keys pressed during IME composition belong to the IME (candidate list, confirming Enter).
  if (e.isComposing || e.keyCode === 229) return null
  if (e.key === ' ' && e.ctrlKey) return 'showAll'
  const plain = !e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey
  if (ctx.popupOpen) {
    if (e.key === 'ArrowDown') return 'next'
    if (e.key === 'ArrowUp') return 'prev'
    if (e.key === 'Escape') return 'close'
    if (e.key === 'Tab' && plain) return 'accept'
    if (isCommitEnter(e) && plain) return 'accept'
    return null
  }
  if (e.key === 'Tab' && plain && !ctx.hasSelection && !ctx.dismissed && emptyRightSide(ctx.beforeCaret)) return 'open'
  return null
}

// After `->`, `→`, `::=` or `|` with nothing typed yet, and not inside a quoted symbol.
const emptyRightSide = (before: string) => /(->|→|::=|\|)\s*$/.test(before) && !/'[^']*$|"[^"]*$/.test(before)

/** Polite screen-reader announcement of the completion list ('' = nothing to say). */
export function suggestionAnnouncement(count: number): string {
  if (count <= 0) return ''
  const noun = count === 1 ? 'návrh' : count < 5 ? 'návrhy' : 'návrhov'
  return `${count} ${noun}, Tab alebo Enter doplní, šípky vyberajú.`
}
